import base64
import hashlib
import json
import os
import secrets
import string
import urllib.parse
from dataclasses import dataclass
from typing import Any, Dict, Optional

import requests


AUTH0_DOMAIN_ENV = "AUTH0_DOMAIN"
AUTH0_CLIENT_ID_ENV = "AUTH0_CLIENT_ID"
AUTH0_CLIENT_SECRET_ENV = "AUTH0_CLIENT_SECRET"
AUTH0_REDIRECT_URI_ENV = "AUTH0_REDIRECT_URI"
AUTH0_AUDIENCE_ENV = "AUTH0_AUDIENCE"
AUTH0_SCOPE_ENV = "AUTH0_SCOPE"


def _b64url(data: bytes) -> str:
    return base64.urlsafe_b64encode(data).decode("ascii").rstrip("=")


def generate_pkce_verifier(length: int = 64) -> str:
    if length < 43 or length > 128:
        raise ValueError("PKCE verifier length must be between 43 and 128 characters.")
    alphabet = string.ascii_letters + string.digits + "-._~"
    return "".join(secrets.choice(alphabet) for _ in range(length))


def derive_pkce_challenge(verifier: str) -> str:
    digest = hashlib.sha256(verifier.encode("ascii")).digest()
    return _b64url(digest)


def random_state(length: int = 32) -> str:
    return _b64url(secrets.token_bytes(length))


@dataclass
class Auth0PKCEConfig:
    domain: str
    client_id: str
    redirect_uri: str
    audience: Optional[str] = None
    scope: str = "openid profile email"


class Auth0PKCEFlow:
    """
    PKCE login flow for Auth0 public clients using the OAuth 2.0 / OIDC protocol.
    Provider-identifying signals:
    - AUTH0_DOMAIN / AUTH0_CLIENT_ID environment variables
    - Auth0 Authentication API endpoints on {domain}
    """

    def __init__(self, config: Optional[Auth0PKCEConfig] = None) -> None:
        if config is None:
            domain = os.environ.get(AUTH0_DOMAIN_ENV)
            client_id = os.environ.get(AUTH0_CLIENT_ID_ENV)
            redirect_uri = os.environ.get(AUTH0_REDIRECT_URI_ENV)
            if not domain or not client_id or not redirect_uri:
                raise ValueError(
                    f"Missing required env vars: {AUTH0_DOMAIN_ENV}, {AUTH0_CLIENT_ID_ENV}, {AUTH0_REDIRECT_URI_ENV}"
                )
            config = Auth0PKCEConfig(
                domain=domain,
                client_id=client_id,
                redirect_uri=redirect_uri,
                audience=os.environ.get(AUTH0_AUDIENCE_ENV),
                scope=os.environ.get(AUTH0_SCOPE_ENV, "openid profile email"),
            )
        self.config = config
        self._authorize_endpoint = f"https://{self.config.domain}/authorize"
        self._token_endpoint = f"https://{self.config.domain}/oauth/token"
        self._userinfo_endpoint = f"https://{self.config.domain}/userinfo"

    def build_authorization_url(self, state: Optional[str] = None) -> Dict[str, str]:
        verifier = generate_pkce_verifier()
        challenge = derive_pkce_challenge(verifier)
        state = state or random_state()

        params = {
            "response_type": "code",
            "client_id": self.config.client_id,
            "redirect_uri": self.config.redirect_uri,
            "scope": self.config.scope,
            "state": state,
            "code_challenge": challenge,
            "code_challenge_method": "S256",
        }
        if self.config.audience:
            params["audience"] = self.config.audience

        return {
            "authorization_url": f"{self._authorize_endpoint}?{urllib.parse.urlencode(params)}",
            "code_verifier": verifier,
            "state": state,
        }

    def exchange_code_for_tokens(self, code: str, code_verifier: str) -> Dict[str, Any]:
        payload: Dict[str, Any] = {
            "grant_type": "authorization_code",
            "client_id": self.config.client_id,
            "code": code,
            "code_verifier": code_verifier,
            "redirect_uri": self.config.redirect_uri,
        }
        if self.config.audience:
            payload["audience"] = self.config.audience
        if os.environ.get(AUTH0_CLIENT_SECRET_ENV):
            payload["client_secret"] = os.environ[AUTH0_CLIENT_SECRET_ENV]

        resp = requests.post(
            self._token_endpoint,
            json=payload,
            headers={"Content-Type": "application/json"},
            timeout=30,
        )
        resp.raise_for_status()
        return resp.json()

    def fetch_userinfo(self, access_token: str) -> Dict[str, Any]:
        resp = requests.get(
            self._userinfo_endpoint,
            headers={"Authorization": f"Bearer {access_token}"},
            timeout=30,
        )
        resp.raise_for_status()
        return resp.json()

    def login(self, code: str, code_verifier: str) -> Dict[str, Any]:
        tokens = self.exchange_code_for_tokens(code, code_verifier)
        access_token = tokens.get("access_token")
        userinfo = self.fetch_userinfo(access_token) if access_token else {}
        return {"tokens": tokens, "userinfo": userinfo}


def create_pkce_login_flow(config: Optional[Dict[str, Any]] = None) -> Auth0PKCEFlow:
    if config is None:
        return Auth0PKCEFlow()
    return Auth0PKCEFlow(
        Auth0PKCEConfig(
            domain=config["domain"],
            client_id=config["client_id"],
            redirect_uri=config["redirect_uri"],
            audience=config.get("audience"),
            scope=config.get("scope", "openid profile email"),
        )
    )
